import sys
from math import sqrt

def is_prime(num):
    if num <= 1: return False
    if num <= 3: return True
    if num % 2 == 0 or num % 3 == 0: return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0: return False
        i += 6
    return True

primes = [p for p in range(2, 1000) if is_prime(p)]
prime_squares = {p**2: p for p in primes}
prime_cubes = {p**3: p for p in primes}

def find_triplet(n):
    for p3 in prime_cubes:
        if p3 >= n: break
        for p2 in prime_squares:
            if p2 + p3 >= n: break
            p1 = n - p2 - p3
            if p1 > 0 and is_prime(p1):
                return f"{p1} {prime_squares[p2]} {prime_cubes[p3]}"
    return "0 0 0"

input = sys.stdin.read().strip().split('\n')
output = []
for num_str in input:
    num = int(num_str)
    if num == 0: break
    output.append(find_triplet(num))

print("\n".join(output))
